previewCss:
.darma-loader-darma-b11-speedometer-gauge { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #ef4444); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .56); position: relative; overflow: hidden; }
.darma-loader-darma-b11-speedometer-gauge::before { content: ''; position: absolute; left: 0; bottom: calc(var(--loader-size, 96px) * -.46); width: var(--loader-size, 96px); height: var(--loader-size, 96px); border-radius: 50%; border: calc(var(--loader-size, 96px) * .08) solid color-mix(in srgb, var(--accent) 20%, transparent); border-top-color: var(--accent-2); border-left-color: var(--accent); box-sizing: border-box; }
.darma-loader-darma-b11-speedometer-gauge span { position: absolute; left: 50%; bottom: 6%; width: calc(var(--loader-size, 96px) * .035); height: 82%; margin-left: calc(var(--loader-size, 96px) * -.0175); background: var(--accent-2); border-radius: 3px; transform-origin: 50% 100%; animation: darma-loader-darma-b11-speedometer-gauge-needle calc(var(--loader-speed, 1s) * 2.2) cubic-bezier(.5, 0, .5, 1) infinite; }
.darma-loader-darma-b11-speedometer-gauge::after { content: ''; position: absolute; left: 50%; bottom: 6%; width: calc(var(--loader-size, 96px) * .12); height: calc(var(--loader-size, 96px) * .12); transform: translate(-50%, 50%); border-radius: 50%; background: var(--accent-2); }
@keyframes darma-loader-darma-b11-speedometer-gauge-needle { 0%, 100% { transform: rotate(-82deg); } 50% { transform: rotate(82deg); } }

